import path from 'node:path';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import type { Logger } from '../logger.js';
import type { Database } from './client.js';

/**
 * Folder generated by drizzle-kit. It sits at `backend/drizzle`, which is three levels up from both
 * `src/infrastructure/database` and `dist/infrastructure/database`.
 */
export const MIGRATIONS_FOLDER = path.resolve(import.meta.dirname, '../../../drizzle');

/** Applies pending migrations; drizzle tracks applied ones in `drizzle.__drizzle_migrations`. */
export async function runMigrations(db: Database, logger: Logger, migrationsFolder = MIGRATIONS_FOLDER) {
  logger.info({ migrationsFolder }, 'Applying database migrations');
  await migrate(db, { migrationsFolder });
  logger.info('Database migrations up to date');
}
